do $test$
declare receiver uuid:=gen_random_uuid();a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();other uuid:=gen_random_uuid();
 post uuid:=gen_random_uuid();op1 uuid:=gen_random_uuid();op2 uuid:=gen_random_uuid();op3 uuid:=gen_random_uuid();another uuid:=gen_random_uuid();r jsonb;before_a bigint;before_b bigint;after_a bigint;sum_gold bigint;
begin
 insert into auth.users(id,created_at) values(receiver,clock_timestamp()),(a,clock_timestamp()),(b,clock_timestamp()),(other,clock_timestamp());
 insert into public.player_profiles(id,nickname) values(receiver,'Ask'||left(receiver::text,6)),(a,'Give'||left(a::text,6)),(b,'Give'||left(b::text,6)),(other,'Other'||left(other::text,6));
 insert into public.player_wallets(user_id,gold,inventory) values(receiver,100,'{"bait":5}'),(a,2000,'{}'),(b,2000,'{}'),(other,0,'{}') on conflict(user_id) do update set gold=excluded.gold,inventory=excluded.inventory;
 select coalesce((select total_xp from app_private.player_experience where user_id=a),0) into before_a;
 select coalesce((select total_xp from app_private.player_experience where user_id=b),0) into before_b;
 select sum(gold) into sum_gold from public.player_wallets where user_id in(receiver,a,b,other);
 perform set_config('request.jwt.claim.sub',receiver::text,true);set local role authenticated;
 begin perform public.begging_create(gen_random_uuid(),E'\t\n',100);raise exception 'EMPTY_STORY_ALLOWED';exception when others then if sqlerrm<>'INVALID_BEGGING' then raise;end if;end;
 r:=public.begging_create(post,'Need a little help',250);
 r:=public.begging_create(post,'Need a little help',250);
 begin perform public.begging_create(post,'Changed story',250);raise exception 'CONFLICT_ALLOWED';exception when others then if sqlerrm<>'OPERATION_CONFLICT' then raise;end if;end;
 begin perform public.begging_create(gen_random_uuid(),'Another story',1000);raise exception 'MULTIPLE_ACTIVE_ALLOWED';exception when others then if sqlerrm<>'BEGGING_ALREADY_ACTIVE' then raise;end if;end;
 begin perform public.begging_give(post,100,gen_random_uuid());raise exception 'SELF_ALLOWED';exception when others then if sqlerrm<>'BEGGING_SELF_GIVE' then raise;end if;end;
 reset role;perform set_config('request.jwt.claim.sub',a::text,true);set local role authenticated;
 begin perform public.begging_give(post,99,gen_random_uuid());raise exception 'UNDER_MINIMUM_ALLOWED';exception when others then if sqlerrm<>'INVALID_BEGGING_AMOUNT' then raise;end if;end;
 r:=public.begging_give(post,100,op1);
 if (r#>>'{receipt,xp}')::integer<>2 or (r#>>'{receipt,replayed}')::boolean then raise exception 'FIRST_RECEIPT_INVALID';end if;
 r:=public.begging_give(post,100,op1);
 if not (r#>>'{receipt,replayed}')::boolean then raise exception 'RETRY_NOT_REPLAYED';end if;
 begin perform public.begging_give(post,101,op1);raise exception 'AMOUNT_CONFLICT_ALLOWED';exception when others then if sqlerrm<>'OPERATION_CONFLICT' then raise;end if;end;
 r:=public.begging_give(post,100,op2);
 if (r#>>'{request,receivedGold}')::integer<>200 then raise exception 'PARTIAL_TOTAL_INVALID';end if;
 reset role;perform set_config('request.jwt.claim.sub',b::text,true);set local role authenticated;
 r:=public.begging_give(post,100,op3);
 if r#>>'{request,status}'<>'completed' or (r#>>'{request,receivedGold}')::integer<>300 then raise exception 'GOAL_NOT_CLOSED';end if;
 r:=public.begging_give(post,100,op3);
 if not (r#>>'{receipt,replayed}')::boolean then raise exception 'FINAL_RETRY_NOT_REPLAYED';end if;
 begin perform public.begging_give(post,100,gen_random_uuid());raise exception 'CLOSED_GIVE_ALLOWED';exception when others then if sqlerrm<>'BEGGING_CLOSED' then raise;end if;end;
 r:=public.begging_history(0);
 if jsonb_array_length(r->'items')<>1 or (r#>>'{items,0,xp}')::integer<>2 or r#>>'{items,0,direction}'<>'sent' then raise exception 'SENT_HISTORY_INVALID';end if;
 reset role;
 if (select sum(gold) from public.player_wallets where user_id in(receiver,a,b,other))<>sum_gold then raise exception 'GOLD_NOT_CONSERVED';end if;
 if (select gold from public.player_wallets where user_id=receiver)<>400 or (select gold from public.player_wallets where user_id=a)<>1800 then raise exception 'WALLET_TOTAL_INVALID';end if;
 if (select inventory from public.player_wallets where user_id=receiver)<>'{"bait":5}'::jsonb then raise exception 'INVENTORY_CHANGED';end if;
 select total_xp into after_a from app_private.player_experience where user_id=a;
 if after_a-before_a<>4 or (select total_xp from app_private.player_experience where user_id=b)-before_b<>2 then raise exception 'XP_NOT_EXACT';end if;
 if (select count(*) from app_private.experience_events where source='begging' and user_id in(a,b))<>3 then raise exception 'XP_RECEIPT_COUNT_INVALID';end if;
 perform set_config('request.jwt.claim.sub',receiver::text,true);set local role authenticated;
 r:=public.begging_history(0);
 if jsonb_array_length(r->'items')<>3 or (r#>>'{items,0,xp}')::integer<>0 or r#>>'{items,0,direction}'<>'received' then raise exception 'RECEIVED_HISTORY_INVALID';end if;
 r:=public.begging_detail(post,0);
 if jsonb_array_length(r->'items')<>3 then raise exception 'PUBLIC_HISTORY_INVALID';end if;
 r:=public.begging_create(another,'Another goal',1000);
 reset role;
 -- A recipient cap failure must leave both balances, history and XP unchanged.
 update public.player_wallets set gold=1000000000 where user_id=receiver;
 perform set_config('request.jwt.claim.sub',a::text,true);set local role authenticated;
 begin perform public.begging_give(another,100,gen_random_uuid());raise exception 'RECIPIENT_CAP_ALLOWED';exception when others then if sqlerrm<>'RECIPIENT_GOLD_LIMIT' then raise;end if;end;
 reset role;update public.player_wallets set gold=400 where user_id=receiver;
 perform set_config('request.jwt.claim.sub',other::text,true);set local role authenticated;
 begin perform public.begging_give(another,100,gen_random_uuid());raise exception 'OVERDRAW_ALLOWED';exception when others then if sqlerrm<>'INSUFFICIENT_GOLD' then raise;end if;end;
 begin perform public.begging_close(another);raise exception 'OTHER_CLOSE_ALLOWED';exception when others then if sqlerrm<>'BEGGING_FORBIDDEN' then raise;end if;end;
 r:=public.begging_history(0);
 if jsonb_array_length(r->'items')<>0 then raise exception 'PRIVATE_HISTORY_LEAK';end if;
 reset role;perform set_config('request.jwt.claim.sub',receiver::text,true);set local role authenticated;
 perform public.begging_close(another);perform public.begging_close(another);reset role;
 if exists(select 1 from app_private.begging_transfers where request_id=another) or (select total_xp from app_private.player_experience where user_id=a)<>after_a then raise exception 'FAILED_GIVE_SIDE_EFFECT';end if;
 if has_function_privilege('anon','public.begging_give(uuid,integer,uuid)','execute') or has_function_privilege('authenticated','app_private.begging_payload(uuid)','execute') then raise exception 'RPC_EXPOSED';end if;
 if has_table_privilege('authenticated','app_private.begging_transfers','SELECT,INSERT,UPDATE,DELETE') or has_table_privilege('authenticated','app_private.begging_requests','SELECT,INSERT,UPDATE,DELETE') then raise exception 'TABLE_EXPOSED';end if;
 -- Keep public receipts and replay semantics if a recipient leaves later.
 delete from auth.users where id=receiver;
 perform set_config('request.jwt.claim.sub',a::text,true);set local role authenticated;
 r:=public.begging_give(post,100,op1);
 if not (r#>>'{receipt,replayed}')::boolean then raise exception 'DEPARTED_RECIPIENT_REPLAY_FAILED';end if;
 reset role;
 if (select total_xp from app_private.player_experience where user_id=a)<>after_a then raise exception 'DEPARTED_REPLAY_ADDED_XP';end if;
 perform set_config('request.jwt.claim.sub','',true);
 begin perform app_private.begging_give(post,100,gen_random_uuid());raise exception 'MISSING_AUTH_ALLOWED';exception when others then if sqlerrm<>'AUTH_REQUIRED' then raise;end if;end;
end $test$;
